// Whether a suggestion panel is visible: a container that appears when search is focused and contains label filter options.
// Based on dev feedback, the panel may appear as a listbox or group near the search box.
export async function suggestionPanel(page: Page): Promise<{ shown: boolean; evidence: string; panel: Locator | null }> {
  // First try to find by role with flexible name matching
  const cands = [
    page.getByRole('listbox', { name: /filter|label/i }),
    page.getByRole('group', { name: /filter|label/i }),
    page.getByRole('region', { name: /filter|label/i }),
    page.getByRole('dialog', { name: /filter|label/i }),
    page.getByRole('menu', { name: /filter|label/i }),
