    page.locator('section,div,aside,[role=region],[role=listbox],[role=group]').filter({
      has: page.getByRole('button', { name: /reminders/i })
    }),
  ];
  for (const c of cands) {
    const n = await c.count();
    const vis = [];
    for (let i = 0; i < n; i++) {
      const el = c.nth(i);
      if (await el.isVisible()) {
