        const hasFilterContent = await el.locator('button,option,checkbox,menuitem').filter({
          hasText: /reminders|filter|label/i
        }).count() > 0;
        if (hasFilterContent) vis.push(el);
      }
    }
    if (vis.length >= 1) return { shown: true, evidence: `${vis.length} match(es)`, panel: vis[vis.length - 1] };
  }
  // Fallback: try to find any container that appears when search is focused
  const searchBox = await searchBox(page).catch(() => null);
  if (searchBox) {
    const nearby = searchBox.locator('..').locator('..').locator('..').locator('section,div,aside,[role=region],[role=listbox],[role=group]');
    const n = await nearby.count();
    for (let i = 0; i < n; i++) {
      const el = nearby.nth(i);
      if (await el.isVisible()) {
        const hasButtons = await el.locator('button').count();
        if (hasButtons > 0) {
          return { shown: true, evidence: 'nearby container with buttons', panel: el };
        }
      }
    }
  }
  return { shown: false, evidence: 'no suggestion container visible', panel: null };
}


